import{z as s,x as A,o as E,c as B,q as r,j as l,D as t,d as o,s as i,S as p,b as a}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"MRoPE / Interleaved MRoPE 时空位置","description":"","frontmatter":{"title":"MRoPE / Interleaved MRoPE 时空位置","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen3-vl-interleaved-mrope.md","filePath":"llm/qwen3-vl-interleaved-mrope.md","lastUpdated":1791413859000}'),d={name:"llm/qwen3-vl-interleaved-mrope.md"};function h(R,e,m,P,w,D){const n=A("Mermaid");return E(),B("div",null,[e[2]||(e[2]=r('<h1 id="mrope-interleaved-mrope-时空位置" tabindex="-1">MRoPE / Interleaved MRoPE 时空位置 <a class="header-anchor" href="#mrope-interleaved-mrope-时空位置" aria-label="Permalink to &quot;MRoPE / Interleaved MRoPE 时空位置&quot;">​</a></h1><div class="epigraph"><p>把旋转频率按时间、高、宽三条轴来编；再把三条轴交错进高低频，视频与图像就可以共用同一套位置几何。</p><footer>—— Wang 等，Qwen2-VL，2024；Qwen3-VL 技术报告</footer></div><p>语言模型默认的 <a href="/llm/rope">RoPE</a> 只有一条位置轴：token 下标。图像有高与宽，视频再加时间。Qwen2-VL 把旋转嵌入拆成时间、高度、宽度三个分量，称为 Multimodal RoPE（MRoPE / M-RoPE）：文本上三轴共用同一套 ID，退化为普通 1D-RoPE；图像上时间 ID 固定、高宽随网格变；视频上时间 ID 随帧递增。Qwen2.5-VL 曾把时间轴对齐到绝对时刻。Qwen3-VL 进一步指出：若把隐维切成三段分别专给 \\(t,h,w\\)，频谱会失衡、长视频变差，于是改为 <strong>Interleaved MRoPE</strong>——三条轴的频率交错分布在整个维度上。图与视频共用这一套交错几何，本篇写清从分块到交错改了什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准 RoPE 对位置 \\(m\\) 施加 \\(R_m\\)，内积只含 \\(n-m\\)。多模态前缀里，一个视觉 token 不能只用「它是第几个标记」：同一行相邻两格应当比「上一行行末与下一行行首」更近；相邻两帧同位置应当在时间轴上近、在空间轴上重合。一维下标会把光栅顺序误当成空间邻近。</p><p><span class="marginnote">直觉类比：RoPE 的频率像钟表——高频平面是秒针（转得快，管精细位移），低频平面是时针（转得慢，管长程距离）。判断「离得远不远」主要靠时针，秒针早转糊了。所以「哪条轴能用上时针」就是位置编码的头等大事。</span></p><p>Qwen2-VL 的回答是给每个视觉 token 三个位置 ID \\((t,h,w)\\)，并把旋转维度划成三组。问题随即变成频谱分配：RoPE 的低频维度负责长程、高频维度负责精细位移。若整段低频都给了高度、时间只分到高频（或反过来），长视频的时间距离会落在不擅长外推的频段上。Qwen3-VL 技术报告写明：分块式 MRoPE 在长视频理解上观察到频谱偏置。需要一种分配，使 \\(t\\)、\\(h\\)、\\(w\\) 都能同时用到低频与高频，而图像（时间轴退化）与视频（三轴全开）仍是同一套公式。</p><p><span class="marginnote">文本 token 的 \\((t,h,w)\\) 取相同值，MRoPE 与 1D-RoPE 等价。不要给纯文本另训一套位置，也不要在图文交错时把文本改成二维 ID。</span></p><h3 id="时间轴曾经绑在「第几帧」上" tabindex="-1">时间轴曾经绑在「第几帧」上 <a class="header-anchor" href="#时间轴曾经绑在「第几帧」上" aria-label="Permalink to &quot;时间轴曾经绑在「第几帧」上&quot;">​</a></h3><p>Qwen2-VL 的时间 ID 随输入帧序号增加，同一段视频抽 \\(8\\) 帧还是 \\(32\\) 帧，相邻 ID 的间隔含义不同，模型难以学会绝对节奏。Qwen2.5-VL 把时间分量对齐到绝对时间，用 ID 间隔表达秒级间隔。Qwen3-VL 认为这一做法在长视频上会让时间 ID 又大又稀疏，改为在帧组前插入文本时间戳；<strong>位置几何</strong>则交给 Interleaved MRoPE 的 \\(t\\) 轴，不再靠绝对时间把 ID 拉得很开。本篇不展开时间戳字符串，只强调：交错的是 RoPE 频率布局，不是把时钟写进文本的那条旁路。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="分块-mrope-三轴切分维度" tabindex="-1">分块 MRoPE：三轴切分维度 <a class="header-anchor" href="#分块-mrope-三轴切分维度" aria-label="Permalink to &quot;分块 MRoPE：三轴切分维度&quot;">​</a></h3><p>把注意力头的旋转维 \\(d_R\\) 分成三段，分别用 \\(t\\)、\\(h\\)、\\(w\\) 作为 <a href="/llm/rope">RoPE</a> 的位置自变量。图像：\\(t\\) 对所有视觉 token 取同一常数（常与该图像在序列中的起点对齐），\\(h,w\\) 取合并后网格上的行、列。视频：每帧（或每个时间 patch）增大 \\(t\\)，帧内 \\(h,w\\) 与单图相同。多图或多段模态拼接时，后一段的位置编号从先前列的最大值继续累加，避免两幅图的 \\((h,w)\\) 撞车。</p><p>对查询、键，形式上仍是分平面旋转，只是第 \\(i\\) 个平面的角度是 \\(m^{(a_i)}\\theta_i\\)，其中 \\(a_i\\in\\{t,h,w\\}\\) 由该平面所属轴决定。分块布局下，\\(a_i\\) 在维度上成三段连续区间。</p><h3 id="interleaved-mrope-轴在频率上轮转" tabindex="-1">Interleaved MRoPE：轴在频率上轮转 <a class="header-anchor" href="#interleaved-mrope-轴在频率上轮转" aria-label="Permalink to &quot;Interleaved MRoPE：轴在频率上轮转&quot;">​</a></h3><p>Qwen3-VL 把 \\(t,h,w\\) <strong>交错</strong>进各旋转平面，使每个轴都均匀出现在低频带与高频带（报告引用 Huang 等 2025 的交错设计）。直观排列从「ttt…hhh…www…」变成「thwthw…」或等价的均匀交织。于是时间距离既能被低频平面慢慢旋转（利于长程），也能被高频平面精细分辨（利于近邻帧）；高、宽同理。图像把 \\(t\\) 设为常数时，属于 \\(t\\) 的那些平面不随空间位置转，空间几何仍由 \\(h,w\\) 平面承担——与视频共用权重，只是时间通道关掉变化。</p><p><span class="marginnote">数字实例：设某注意力头有 128 个旋转维，即 64 个旋转平面。分块布局把 64 个平面切成连续三段，一条轴独占一段；交错布局则按约 1:1:1 把 t/h/w 轮流撒进全部 64 个平面。平面总数、参数量、计算量都不变，变的只是「平面归谁」这张分配表。</span></p> \\[(R_{t,h,w}q)^{\\top}(R_{t&#39;,h&#39;,w&#39;}k) \\]<p>仍由各平面相对位移决定；交错改变的是「哪一个 \\(\\theta_i\\) 乘在哪一条轴上」，不改变 RoPE 的相对性。</p>',19)),(E(),l(p,null,{default:t(()=>[i(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20Text%5B%22%E6%96%87%E6%9C%AC%3A%20t%20%E7%AD%89%E4%BA%8E%20h%20%E7%AD%89%E4%BA%8E%20w%22%5D%20--%3E%20Rope%5B%22%E5%90%8C%E4%B8%80%E5%A5%97%E6%97%8B%E8%BD%AC%22%5D%0A%20%20Img%5B%22%E5%9B%BE%E5%83%8F%3A%20t%20%E5%9B%BA%E5%AE%9A%20h%20w%20%E8%B5%B0%E7%BD%91%E6%A0%BC%22%5D%20--%3E%20Rope%0A%20%20Vid%5B%22%E8%A7%86%E9%A2%91%3A%20t%20%E9%9A%8F%E5%B8%A7%20h%20w%20%E5%90%8C%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20Rope%0A%20%20Rope%20--%3E%20Blk%5B%22%E5%88%86%E5%9D%97%3A%20%E7%BB%B4%E5%BA%A6%E5%88%87%E6%88%90%E4%B8%89%E6%AE%B5%22%5D%0A%20%20Rope%20--%3E%20Int%5B%22%E4%BA%A4%E9%94%99%3A%20%E4%B8%89%E8%BD%B4%E8%BD%AE%E6%B5%81%E5%8D%A0%E7%94%A8%E9%A2%91%E7%8E%87%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[a("span",{class:"marginnote"},"交错是频率分配，不是把一个 token 的位置改成三个下标的函数值再相加。实现上仍是按平面选一个标量位置去乘 \\(\\theta_i\\)，只是平面到轴的映射从分段改成交织。")],-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[o("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,"RoPE 的相对内积对「未见过的大位移」敏感的是频谱：高频平面在大位移上已经转乱，只剩低频还在编码距离。长视频的帧间 \\(t\\) 差可以很大；若 \\(t\\) 只分到高频段，时间轴等于几乎没有可用的长程几何。交错强制每个轴都有慢旋转平面，长程时间与长程空间不再互相抢低频配额。",-1)),(E(),l(p,null,{default:t(()=>[i(n,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20BLK%5B%22%E5%88%86%E5%9D%97%EF%BC%9Attt%E2%80%A6hhh%E2%80%A6www%E2%80%A6%22%5D%0A%20%20%20%20B1%5B%22t%20%E7%8B%AC%E5%8D%A0%E4%BD%8E%E9%A2%91%E6%AE%B5%22%5D%20--%3E%20B2%5B%22h%20%E7%8B%AC%E5%8D%A0%E4%B8%AD%E9%A2%91%E6%AE%B5%22%5D%20--%3E%20B3%5B%22w%20%E7%8B%AC%E5%8D%A0%E9%AB%98%E9%A2%91%E6%AE%B5%22%5D%0A%20%20end%0A%20%20subgraph%20INT%5B%22%E4%BA%A4%E9%94%99%EF%BC%9Athwthw%E2%80%A6%22%5D%0A%20%20%20%20I1%5B%22%E4%BD%8E%E9%A2%91%EF%BC%9At%20h%20w%20%E8%BD%AE%E6%B5%81%22%5D%20--%3E%20I2%5B%22%E4%B8%AD%E9%A2%91%EF%BC%9A%E8%BD%AE%E6%B5%81%22%5D%20--%3E%20I3%5B%22%E9%AB%98%E9%A2%91%EF%BC%9A%E8%BD%AE%E6%B5%81%22%5D%0A%20%20end%0A%20%20B3%20-.%E9%95%BF%E8%A7%86%E9%A2%91%E6%97%B6%E9%97%B4%E7%BC%BA%E6%85%A2%E5%B9%B3%E9%9D%A2.-%3E%20I1%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=r('<p>图像与视频共用，靠的是退化规则而不是两套权重：单图把时间差置零，交错布局里属于 \\(t\\) 的平面对所有该图 token 施加同一旋转，相当于公共相位，不破坏 \\(h,w\\) 的相对结构。训练时图、视频、文本可以混在同一批次，位置模块不必切换。这比「图像用 2D-RoPE、视频另接时间编码头」更省一套接口，也避免模态交界处位置定义不一致。</p><p>Qwen2.5-VL 的绝对时间对齐，是在分块 MRoPE 上改变 \\(t\\) 的<strong>取值</strong>（与秒挂钩）；Interleaved MRoPE 改变的是 \\(t\\) 乘在哪些<strong>频率</strong>上。二者层不同。Qwen3-VL 用文本时间戳承接「现在是第几秒」，用交错 MRoPE 承接「token 在三维网格上的相对几何」。</p><p><span class="marginnote">ViT 内部另有 2D-RoPE，编码的是尚未合并的 patch 网格。LLM 侧 MRoPE 编码的是合并后的视觉 token 以及文本。两套旋转不要共用同一套 \\((h,w)\\) 计数，除非实现明确对齐了 merge 前后的坐标。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>交错不能取消长度外推问题：频率底座、YaRN 一类插值仍可能需要。Qwen3-VL 公开材料提到超长上下文时 MRoPE 的 section 划分与较小的 YaRN factor，因为交错后位置 ID 增长方式与纯 1D 不同。复现时不要把纯文本 YaRN 的默认因子直接套到视觉长视频上。</p><p><span class="marginnote">常见误区：初学者容易以为交错是一种「提效」改动，能让模型更快或更省显存。实际上参数量、KV 缓存、计算量与分块版完全一样——它只是把「哪个频率乘哪条轴」的分配表重排，专门修长视频上时间轴借不到低频的病，静态图像任务上收益很小。</span></p><p>分块 MRoPE 并非「错了所以必须立刻作废」：Qwen2-VL 已用它提升视频基准相对 1D-RoPE 的表现。交错是针对分块频谱偏置的修正，主场是长时序。短图、单帧任务上两者差距会小得多，不要用 OCRBench 一类静态任务去证明交错「全面替代」分块。</p><p>实现边界：必须按头维的配对平面交织，量化与 KV 缓存要缓存旋转前还是旋转后的键，与普通 RoPE 相同；多轴只是多了一张「平面 → 轴」查找表。若错误地把 \\(t,h,w\\) 加成一个标量再送进 1D-RoPE，三维相对性全部丢失。另一边界是多图：第二张图的 \\(t\\) 或全局偏移必须与第一张断开空间网格，否则两张图的左上角会共享 \\((h,w)\\)，模型会以为它们在空间上重合。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MRoPE 把 RoPE 拆成时间、高、宽三个位置 ID：文本三轴相同，图像 \\(t\\) 固定、视频 \\(t\\) 随帧，图与视频共用空间轴。</li><li>分块布局把维度连续切给三轴，低频配额不均，长视频易伤；Interleaved MRoPE 让三轴轮流占用高低频。</li><li>交错改频率分配，不改相对旋转的代数；Qwen3-VL 另用文本时间戳表达绝对时刻，与 MRoPE 分工。</li><li>图像是时间轴退化后的同一套几何，不必为静图再训 2D 专用位置模块。</li><li>出处：Wang 等，<em>Qwen2-VL</em>，2024（MRoPE 定义）；Qwen2.5-VL 技术报告（绝对时间对齐的 \\(t\\)）；Qwen3-VL 技术报告（Interleaved MRoPE）；RoPE 见 Su 等。</li></ul>',10))])}const M=s(d,[["render",h]]);export{I as __pageData,M as default};
